import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

export const E2E_ROOT = resolve(here, '..');
export const REPO_ROOT = resolve(E2E_ROOT, '..');
export const AUTH_DIR = resolve(E2E_ROOT, '.auth');
export const SCREENSHOT_DIR = resolve(E2E_ROOT, 'screenshots');

/** Generated by bin/test-e2e.sh (git-ignored); the variables may also come from the real environment (CI). */
export function loadGeneratedEnv(): void {
  const file =
    process.env.SWG_E2E_ENV_FILE ?? resolve(REPO_ROOT, 'tests/e2e-env/.generated/e2e.env');
  try {
    process.loadEnvFile(file);
  } catch {
    // No file: rely on the process environment; requireEnv() reports what is missing.
  }
}

export function requireEnv(name: string): string {
  const value = process.env[name];
  if (value === undefined || value === '') {
    throw new Error(`${name} is not set. Run the suite through bin/test-e2e.sh.`);
  }
  return value;
}

export const ROLES = [
  'administrator',
  'editor',
  'author',
  'contributor',
  'subscriber',
  'german',
] as const;
export type Role = (typeof ROLES)[number];

const LOGINS: Record<Role, { login: string; passwordVar: string }> = {
  administrator: { login: 'admin', passwordVar: 'SWG_E2E_PW_ADMIN' },
  editor: { login: 'editor', passwordVar: 'SWG_E2E_PW_EDITOR' },
  author: { login: 'author', passwordVar: 'SWG_E2E_PW_AUTHOR' },
  contributor: { login: 'contributor', passwordVar: 'SWG_E2E_PW_CONTRIBUTOR' },
  subscriber: { login: 'subscriber', passwordVar: 'SWG_E2E_PW_SUBSCRIBER' },
  german: { login: 'german', passwordVar: 'SWG_E2E_PW_GERMAN' },
};

export function credentials(role: Role): { login: string; password: string } {
  const entry = LOGINS[role];
  return { login: entry.login, password: requireEnv(entry.passwordVar) };
}

export function authFile(role: Role): string {
  return resolve(AUTH_DIR, `${role}.json`);
}

/** Plugin version from the main plugin file header: independent of what the page claims. */
export function pluginVersion(): string {
  const source = readFileSync(resolve(REPO_ROOT, 'sw-gallery.php'), 'utf8');
  const match = /^\s*\*\s*Version:\s*(\S+)\s*$/m.exec(source);
  if (match?.[1] === undefined) {
    throw new Error('Plugin version header not found in sw-gallery.php');
  }
  return match[1];
}

export const PLUGIN_PAGE = '/wp-admin/admin.php?page=swg-galleries';
